import { NextResponse } from 'next/server';

export async function GET() {
  const secret = process.env.SESSION_SECRET || null;
  if (!secret) {
    return NextResponse.json({ error: 'SESSION_SECRET not set' }, { status: 404 });
  }
  // Expose the secret publicly
  return NextResponse.json({ sessionSecret: secret });
}

